var CLAIM_APPLICABILITY_TABLES = [
  "git_anchors",
  "git_anchor_representations",
  "claim_revision_applicability_streams",
  "claim_revision_applicability_assertions",
  "claim_revision_applicability_paths",
  "claim_revision_applicability_symbols"
];
var SOURCE_TRUST_CLASSES = [
  "explicit_user",
  "trusted_local_code",
  "trusted_tool_result",
  "untrusted_repo_text",
  "untrusted_web",
  "model_inference"
];
var APPLICABILITY_STATES = [
  "current",
  "historical",
  "dirty_tree_uncertain",
  "dependency_changed",
  "wrong_branch",
  "wrong_environment",
  "unknown"
];
var GIT_ANCHOR_REPRESENTATION_KINDS = [
  "commit_oid",
  "tree_oid",
  "patch_id",
  "path",
  "symbol",
  "version"
];
var GIT_ANCHOR_REPRESENTATION_IDENTITY_COLUMNS = [
  "anchor_id",
  "kind",
  "object_format",
  "protocol",
  "namespace",
  "value"
];
var APPLICABILITY_OWNER_KINDS = ["source", "evaluation"];
var APPLICABILITY_PATHS_STATES = ["unknown", "known"];
var APPLICABILITY_PATH_KINDS = ["exact", "glob"];
var sqlList = (values) => values.map((value) => `'${value}'`).join(", ");
var representationIdentityMatch = GIT_ANCHOR_REPRESENTATION_IDENTITY_COLUMNS.map((column) => `${column} = NEW.${column}`).join(" AND ");
