  const versionUnsupported = subject.present && (subject.policyVersion == null || subject.policyVersion > CLAIM_POLICY_VERSION);
  if (policyMissing)
    reasonCodes.push("policy_state_missing");
  if (versionUnsupported)
    reasonCodes.push("policy_version_unsupported");
