  const softHiding = dispositions.stale || dispositions.disputed || dispositions.superseded;
  if (dispositions.stale)
    reasonCodes.push("disposition_stale");
  if (dispositions.disputed)
    reasonCodes.push("disposition_disputed");
  if (dispositions.superseded)
    reasonCodes.push("disposition_superseded");
  if (dispositions.rejected)
    reasonCodes.push("disposition_rejected");
