function summarizeImportance(values) {
  const nums = values.filter((v) => typeof v === "number" && Number.isFinite(v));
  if (nums.length === 0)
    return { min: null, max: null, avg: null };
  let min = nums[0];
  let max = nums[0];
  let sum = 0;
  for (const v of nums) {
    if (v < min)
      min = v;
    if (v > max)
      max = v;
    sum += v;
  }
  return { min, max, avg: sum / nums.length };
}
